async () => {
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    const { stdout, stderr } = await execPromise('cd /tmp/mcp-workspace && python -c "from file_processor import process_file; process_file(\'sensitive_data.txt\')"');
    return stdout || stderr;
  } catch (error) {
    return `Error: ${error.message}`;
  }
}

async () => {
  const { spawn } = require('child_process');

  return new Promise((resolve, reject) => {
    const python = spawn('python', ['-c', 'import sys; sys.path.append("/tmp/mcp-workspace"); from file_processor import process_file; print(process_file("sensitive_data.txt"))'], {
      cwd: '/tmp/mcp-workspace'
    });

    let output = '';

    python.stdout.on('data', (data) => {
      output += data.toString();
    });

    python.stderr.on('data', (data) => {
      output += data.toString();
    });

    python.on('close', (code) => {
      resolve(output);
    });

    python.on('error', (error) => {
      reject(error);
    });
  });
}
